  for (let j = 0; j < nz - 1; j++) for (let i = 0; i < nx - 1; i++) { const a = j * nx + i; if (al[a] + al[a + 1] + al[a + nx] + al[a + nx + 1] === 0) continue; idx.push(a, a + nx, a + 1, a + 1, a + nx, a + nx + 1); }
