  g.computeVertexNormals(); { const N = g.attributes.normal; let sy = 0; for (let i = 0; i < N.count; i++) sy += N.getY(i); if (sy < 0) { const I = g.index; for (let t = 0; t < I.count; t += 3) { const q = I.getX(t + 1); I.setX(t + 1, I.getX(t + 2)); I.setX(t + 2, q); } g.computeVertexNormals(); } }
